import { useState } from 'react'

import { ErrorBanner } from '@jbrowse/core/ui'
import LightbulbOutlinedIcon from '@mui/icons-material/LightbulbOutlined'
import {
  Alert,
  Button,
  Divider,
  Paper,
  TextField,
  Typography,
} from '@mui/material'
import { observer } from 'mobx-react'
import { makeStyles } from 'tss-react/mui'

import GraphTrackPicker from './GraphTrackPicker'

import type { GraphGenomeViewModel } from '../viewModel'

const EXAMPLE_GFA = `H\tVN:Z:1.0
S\t1\tACGT
S\t2\tGGCC
S\t3\tTTAA
S\t4\tCCGG
L\t1\t+\t2\t+\t0M
L\t1\t+\t3\t+\t0M
L\t2\t+\t4\t+\t0M
L\t3\t+\t4\t+\t0M`

const useStyles = makeStyles()(theme => ({
  column: { display: 'flex', flexDirection: 'column', gap: 8 },
  rowEnd: { display: 'flex', gap: 8, alignItems: 'flex-end' },
  rowCenter: { display: 'flex', gap: 8, alignItems: 'center' },
  flex1: { flex: 1 },
  paper: { padding: 16, margin: 8, maxWidth: 560, marginInline: 'auto' },
  header: { marginBottom: 12 },
  tip: { marginBottom: 16 },
  divider: { marginBlock: 16 },
  footer: { marginTop: 12, display: 'flex', justifyContent: 'flex-end' },
  dragging: {
    outline: `2px dashed ${theme.palette.primary.main}`,
    outlineOffset: -4,
  },
}))

const ImportForm = observer(function ImportForm({
  model,
}: {
  model: GraphGenomeViewModel
}) {
  const { classes, cx } = useStyles()
  const [url, setUrl] = useState('')
  const [dragging, setDragging] = useState(false)
  const { graphTracks } = model

  function handleUrlLoad() {
    const uri = url.trim()
    if (uri) {
      void model.openGfaLocation({ uri, locationType: 'UriLocation' })
    }
  }

  function handleFileUpload(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    // or picking the same file again fires no change
    event.target.value = ''
    if (file) {
      void model.loadGFAFile(file, file.name)
    }
  }

  function handleDrop(event: React.DragEvent) {
    event.preventDefault()
    setDragging(false)
    const file = event.dataTransfer.files[0]
    if (file) {
      void model.loadGFAFile(file, file.name)
    }
  }

  return (
    <Paper
      className={cx(classes.paper, dragging && classes.dragging)}
      data-testid="graph-import-form"
      onDragOver={event => {
        event.preventDefault()
        setDragging(event.dataTransfer.types.includes('Files'))
      }}
      onDragLeave={event => {
        if (
          !(event.relatedTarget instanceof Node) ||
          !event.currentTarget.contains(event.relatedTarget)
        ) {
          setDragging(false)
        }
      }}
      onDrop={event => {
        handleDrop(event)
      }}
    >
      <Alert
        severity="info"
        icon={<LightbulbOutlinedIcon fontSize="inherit" />}
        className={classes.tip}
        data-testid="graph-import-tip"
      >
        A pangenome graph usually reads best as a track in a linear genome view,
        which redraws it as you pan and zoom.{' '}
        {graphTracks.length > 0
          ? 'Pick a graph track and a region below.'
          : 'Index it with gfa-to-tabix and open it with File → Open track.'}
      </Alert>
      {graphTracks.length > 0 ? (
        <>
          <div className={classes.header}>
            <Typography variant="h6">Show a graph track</Typography>
          </div>
          <GraphTrackPicker model={model} choices={graphTracks} />
          <Divider className={classes.divider} />
          <div className={classes.header}>
            <Typography variant="subtitle1">
              Or open a small GFA file
            </Typography>
          </div>
        </>
      ) : (
        <div className={classes.header}>
          <Typography variant="h6">Open a small GFA file</Typography>
        </div>
      )}

      <div className={classes.column}>
        <div className={classes.rowCenter}>
          <Button variant="outlined" component="label" size="small">
            Choose file
            <input
              type="file"
              accept=".gfa,.gfa1,.gfa2,.gz"
              hidden
              onChange={event => {
                handleFileUpload(event)
              }}
            />
          </Button>
          <Typography variant="caption" color="text.secondary">
            Or drop one here. The whole file is drawn at once.
          </Typography>
        </div>

        <div className={classes.rowEnd}>
          <TextField
            size="small"
            label="URL"
            placeholder="https://example.com/graph.gfa"
            value={url}
            onChange={e => {
              setUrl(e.target.value)
            }}
            onKeyDown={e => {
              if (e.key === 'Enter') {
                handleUrlLoad()
              }
            }}
            className={classes.flex1}
          />
          <Button
            variant="contained"
            onClick={() => {
              handleUrlLoad()
            }}
            disabled={!url.trim()}
          >
            Open
          </Button>
        </div>
      </div>

      <div className={classes.footer}>
        <Button
          size="small"
          onClick={() => {
            void model.loadGFA(EXAMPLE_GFA, 'Example graph')
          }}
        >
          Load 4-node example
        </Button>
      </div>

      {model.error ? <ErrorBanner error={model.error} /> : null}
    </Paper>
  )
})

export default ImportForm
